WITH unpacked AS (SELECT id, host, latency_ms, status_code, context['region'] AS region, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs WHERE host = 'h1') SELECT id, host, latency_ms, status_code, region, user_tier, FIRST_VALUE(user_tier, TRUE) OVER (PARTITION BY host ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_user_tier, PERCENT_RANK() OVER w_ordered AS status_code_percent_rank, CORR(status_code, latency_ms) OVER (PARTITION BY host) AS corr_status_code_latency_ms, ROW_NUMBER() OVER (PARTITION BY host ORDER BY status_code DESC, id) AS row_seq FROM unpacked WINDOW w_ordered AS (PARTITION BY host ORDER BY status_code);
